function logGotRedemptionSignature(bytes32 _digest, bytes32 _r, bytes32 _s)
     public returns (bool) {
    if (!approvedToLog(msg.sender)) return true;
    emit GotRedemptionSignature(
        msg.sender,
        _digest,
        _r,
        _s,
        block.timestamp
    );
    return true;
}

